            A("12.15", "Нарушение правил расположения ТС на проезжей части", "4. Выезд в нарушение Правил дорожного движения на полосу, предназначенную для встречного движения, либо на трамвайные пути встречного направления — влечёт наложение административного штрафа в размере пяти тысяч рублей или лишение права управления транспортными средствами на срок от четырёх до шести месяцев."),
            A("12.16", "Несоблюдение требований знаков или разметки", "1. Несоблюдение требований, предписанных дорожными знаками или разметкой проезжей части дороги, за исключением случаев, предусмотренных другими статьями настоящей главы, — влечёт предупреждение или наложение административного штрафа в размере пятисот рублей."),
            A("12.18", "Непредоставление преимущества пешеходам", "Невыполнение требования Правил дорожного движения уступить дорогу пешеходам, велосипедистам или иным участникам дорожного движения, пользующимся преимуществом в движении, — влечёт наложение административного штрафа в размере от одной тысячи пятисот до двух тысяч пятисот рублей."),
            A("12.19", "Нарушение правил остановки или стоянки", "1. Нарушение правил остановки или стоянки транспортных средств, за исключением случаев, предусмотренных другими частями настоящей статьи, — влечёт предупреждение или наложение административного штрафа в размере пятисот рублей."),
            A("20.1", "Мелкое хулиганство", "1. Мелкое хулиганство, то есть нарушение общественного порядка, выражающее явное неуважение к обществу, сопровождающееся нецензурной бранью в общественных местах, оскорбительным приставанием к гражданам, а равно уничтожением или повреждением чужого имущества, — влечёт наложение административного штрафа в размере от пятисот до одной тысячи рублей или административный арест на срок до пятнадцати суток."),
            A("20.20", "Распитие алкоголя в запрещённых местах", "1. Потребление (распитие) алкогольной продукции в местах, запрещённых федеральным законом, — влечёт наложение административного штрафа в размере от ста до трёхсот рублей."),
            A("20.21", "Появление в состоянии опьянения", "Появление на улицах, стадионах, в скверах, парках, в транспортном средстве общего пользования, в других общественных местах в состоянии опьянения, оскорбляющем человеческое достоинство и общественную нравственность, — влечёт наложение административного штрафа в размере от пятисот до одной тысячи пятисот рублей или административный арест на срок до пятнадцати суток."),
            A("20.25", "Уклонение от исполнения административного наказания", "1. Неуплата административного штрафа в срок, предусмотренный настоящим Кодексом, — влечёт наложение административного штрафа в двукратном размере суммы неуплаченного административного штрафа, но не менее одной тысячи рублей, либо административный арест на срок до пятнадцати суток, либо обязательные работы на срок до пятидесяти часов.")
        )
        koap.forEachIndexed { i, a ->
            artForce("koap-${a.n.replace('.', '-')}", "koap", i + 1, a.n, a.t, a.b)
        }

        // Other codes — minimal anchors
        doc("uk", "Уголовный кодекс Российской Федерации", "code", "УК РФ")
        art("uk-14", "uk", 14, "14", "Понятие преступления", "1. Преступлением признаётся виновно совершённое общественно опасное деяние, запрещённое настоящим Кодексом под угрозой наказания.")
        art("uk-158", "uk", 158, "158", "Кража", "1. Кража, то есть тайное хищение чужого имущества.")

        doc("gk", "Гражданский кодекс Российской Федерации", "code", "ГК РФ")
        art("gk-1", "gk", 1, "1", "Основные начала гражданского законодательства", "1. Гражданское законодательство основывается на признании равенства участников регулируемых им отношений, неприкосновенности собственности, свободы договора.")

        doc("tk", "Трудовой кодекс Российской Федерации", "code", "ТК РФ")
        art("tk-1", "tk", 1, "1", "Цели и задачи трудового законодательства", "Целями трудового законодательства являются установление государственных гарантий трудовых прав и свобод граждан, создание благоприятных условий труда, защита прав и интересов работников и работодателей.")

        doc("nk", "Налоговый кодекс Российской Федерации", "code", "НК РФ")
        art("nk-1", "nk", 1, "1", "Законодательство о налогах и сборах", "Законодательство Российской Федерации о налогах и сборах состоит из настоящего Кодекса и принятых в соответствии с ним федеральных законов о налогах и сборах.")

        doc("zhk", "Жилищный кодекс Российской Федерации", "code", "ЖК РФ")
        art("zhk-1", "zhk", 1, "1", "Основные начала жилищного законодательства", "Жилищное законодательство основывается на необходимости обеспечения органами государственной власти и органами местного самоуправления условий для осуществления гражданами права на жилище.")

        doc("zk", "Земельный кодекс Российской Федерации", "code", "ЗК РФ")
        art("zk-1", "zk", 1, "1", "Основные начала земельного законодательства", "Земельное законодательство регулирует отношения по использованию и охране земель в Российской Федерации.")

        doc("apk", "Арбитражный процессуальный кодекс Российской Федерации", "code", "АПК РФ")
        art("apk-1", "apk", 1, "1", "Осуществление правосудия", "Правосудие в сфере предпринимательской и иной экономической деятельности осуществляется арбитражными судами.")

        doc("bk", "Бюджетный кодекс Российской Федерации", "code", "БК РФ")
        art("bk-1", "bk", 1, "1", "Бюджетное законодательство", "Бюджетное законодательство Российской Федерации состоит из настоящего Кодекса и принятых в соответствии с ним федеральных законов.")

        doc("fz", "Федеральные законы", "code", "ФЗ")
        art("fz-1", "fz", 1, "1", "Общие положения", "Федеральные законы принимаются в соответствии с Конституцией Российской Федерации и имеют прямое действие на всей территории Российской Федерации.")
    }
